create table if not exists public.os_learning_outcomes (id uuid primary key default gen_random_uuid(), agent_run_id uuid references public.os_agent_runs(id) on delete set null, agent_action_id uuid references public.os_agent_actions(id) on delete set null, service_id uuid references public.music_services(id) on delete set null, outcome_type text not null, predicted jsonb not null default '{}'::jsonb, observed jsonb not null default '{}'::jsonb, delta jsonb not null default '{}'::jsonb, evidence jsonb not null default '{}'::jsonb, outcome_status text not null default 'observed', observed_at timestamptz not null default now(), created_at timestamptz not null default now());
create index if not exists os_learning_outcomes_service_idx on public.os_learning_outcomes(service_id, observed_at desc);
create index if not exists os_learning_outcomes_agent_idx on public.os_learning_outcomes(agent_run_id, observed_at desc);
alter table public.os_learning_outcomes enable row level security;
revoke all on public.os_learning_outcomes from anon, authenticated;
create or replace function public.os_record_learning_outcome(p_agent_run_id uuid,p_agent_action_id uuid,p_service_id uuid,p_outcome_type text,p_predicted jsonb,p_observed jsonb,p_delta jsonb,p_evidence jsonb,p_status text default 'observed') returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not public.is_admin() then raise exception 'admin_required'; end if; insert into public.os_learning_outcomes(agent_run_id,agent_action_id,service_id,outcome_type,predicted,observed,delta,evidence,outcome_status) values(p_agent_run_id,p_agent_action_id,p_service_id,p_outcome_type,coalesce(p_predicted,'{}'),coalesce(p_observed,'{}'),coalesce(p_delta,'{}'),coalesce(p_evidence,'{}'),p_status) returning id into v_id; return v_id; end; $$;
revoke all on function public.os_record_learning_outcome(uuid,uuid,uuid,text,jsonb,jsonb,jsonb,jsonb,text) from public,anon,authenticated;
grant execute on function public.os_record_learning_outcome(uuid,uuid,uuid,text,jsonb,jsonb,jsonb,jsonb,text) to authenticated;
create or replace function public.os_close_setlist_learning_loop_internal(p_service_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_run record; v_observed jsonb; v_predicted jsonb; v_delta jsonb; v_count int:=0; begin for v_run in select r.id as run_id,r.input_context,r.result from public.os_agent_runs r join public.os_agents ag on ag.id=r.agent_id where ag.key='setlist_agent' and (r.input_context->>'service_id')::uuid=p_service_id and r.started_at>now()-interval '14 days' and not exists(select 1 from public.os_learning_outcomes o where o.agent_run_id=r.id) order by r.started_at desc loop v_predicted:=coalesce(v_run.result,'{}'::jsonb); select jsonb_build_object('setlist_exists',exists(select 1 from public.music_setlists s where s.service_id=p_service_id and coalesce(s.status,'draft') in ('draft','published')),'setlist_items',coalesce((select count(*) from public.music_setlist_items i join public.music_setlists s on s.id=i.setlist_id where s.service_id=p_service_id),0),'service_date',v_run.input_context->>'service_date','captured_at',now()) into v_observed; v_delta:=jsonb_build_object('setlist_created',coalesce((v_observed->>'setlist_exists')::boolean,false) and coalesce((v_observed->>'setlist_items')::int,0)>0); insert into public.os_learning_outcomes(agent_run_id,service_id,outcome_type,predicted,observed,delta,evidence) values(v_run.run_id,p_service_id,'setlist_followthrough',v_predicted,v_observed,v_delta,jsonb_build_object('method','database_requery','verified',true,'source','autonomous_learning_worker')); v_count:=v_count+1; end loop; return jsonb_build_object('ok',true,'service_id',p_service_id,'outcomes_recorded',v_count); end; $$;
revoke all on function public.os_close_setlist_learning_loop_internal(uuid) from public,anon,authenticated;
create or replace function public.os_run_learning_loop_worker() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_service record; v_result jsonb; v_total int:=0; begin for v_service in select id from public.music_services where starts_at between now()-interval '7 days' and now()+interval '14 days' and coalesce(status,'scheduled') not in ('cancelled','archived') loop select public.os_close_setlist_learning_loop_internal(v_service.id) into v_result; v_total:=v_total+coalesce((v_result->>'outcomes_recorded')::int,0); end loop; return jsonb_build_object('ok',true,'outcomes_recorded',v_total); end; $$;
revoke all on function public.os_run_learning_loop_worker() from public,anon,authenticated;
select cron.schedule('learning-loop-worker','*/5 * * * *', $$select public.os_run_learning_loop_worker();$$) where not exists(select 1 from cron.job where jobname='learning-loop-worker');